  render(){const root=super.render();const toolbar=this.element('div','widget-subheading');this.dateInput=this.element('input','date-control');this.dateInput.type='date';this.dateInput.value=this.dashboard.store.selectedDate;this.dateInput.setAttribute('aria-label','Дата задач');const filter=this.element('select','period-select');filter.setAttribute('aria-label','Показать задачи');for(const[value,text]of[['day','На этот день'],['all','Все задачи']]){const option=this.element('option','',text);option.value=value;filter.append(option);}toolbar.append(this.dateInput,filter);this.listen(this.dateInput,'change',()=>this.dashboard.store.selectDate(this.dateInput.value));this.listen(filter,'change',()=>{this.filter=filter.value;this.update();});this.listen(this.dashboard.store,'date',()=>{this.dateInput.value=this.dashboard.store.selectedDate;this.update();});this.summary=this.element('div','task-summary');const track=this.element('div','progress-track');this.progress=this.element('i');track.append(this.progress);this.list=this.element('ul','task-list');const form=this.element('form','task-form');this.input=this.element('input','text-input');this.input.placeholder='Что хочется сделать?';this.input.maxLength=180;this.input.required=true;this.input.setAttribute('aria-label','Новая задача');this.priority=this.element('select','priority-select');this.priority.setAttribute('aria-label','Приоритет новой задачи');for(const[value,text]of[['normal','Обычный'],['high','Важное'],['low','Без спешки']]){const option=this.element('option','',text);option.value=value;this.priority.append(option);}const add=this.element('button','','+');add.type='submit';add.setAttribute('aria-label','Добавить задачу');form.append(this.input,this.priority,add);this.listen(form,'submit',event=>{event.preventDefault();if(this.input.value.trim()){try{this.addTask(this.input.value);this.input.value='';this.input.focus();}catch(error){this.dashboard.announce(error.message);}}});this.listen(this.list,'change',event=>{const id=event.target.dataset.task;if(id){this.toggleTask(id);for(const check of this.list.querySelectorAll('[data-task]'))if(check.dataset.task===id)check.focus();}});this.listen(this.list,'click',event=>{const button=event.target.closest('[data-delete]');if(button){this.removeTask(button.dataset.delete);this.input.focus();}});this.content.append(toolbar,this.summary,track,this.list,form,this.element('p','micro-label','Не всё сразу. Сначала — важное.'));this.update();return root;}
  get tasks(){return this.#tasks.map(t=>({...t}));}
  addTask(text){text=String(text).trim().slice(0,180);if(!text||this.#tasks.length>=200)throw new Error('Введите задачу (не более 200 задач в виджете)');const task={id:crypto.randomUUID(),text,done:false,date:this.dashboard.store.selectedDate,priority:this.priority?.value||'normal',completedAt:null};this.#tasks.push(task);this.update();this.changed();return {...task};}
