// dist/js/FocusWidget.js


class FocusWidget extends UIComponent {
  constructor(config, dashboard) {
    super({ ...config, title: 'Время для фокуса', symbol: '◷' }, dashboard);
    this.duration = [15, 25, 45].includes(config.state?.duration) ? config.state.duration : 25;
    this.remaining = Number.isFinite(config.state?.remaining) ? Math.max(0, Math.min(this.duration * 60, config.state.remaining)) : this.duration * 60;
    this.running = false;
    this.category = ['Творчество','Развитие','Личное'].includes(config.state?.category) ? config.state.category : 'Личное';
  }
  render() {
    const root = super.render();
    const inner = this.element('div', 'focus-inner'); const numbers = this.element('div');
    this.value = this.element('div', 'timer-value'); this.value.setAttribute('role', 'timer'); this.value.setAttribute('aria-label', 'Осталось времени');
    this.caption = this.element('p', 'focus-caption', 'ОДНА ЗАДАЧА. ПОЛНОЕ ВНИМАНИЕ.'); numbers.append(this.value, this.caption);
    this.ring = this.element('div', 'focus-ring'); this.ring.setAttribute('aria-hidden', 'true'); this.ring.append(this.element('span', '', '✳'));
    inner.append(numbers, this.ring);
    const footer = this.element('div', 'focus-footer');
    this.start = this.button('Начать', 'Начать фокус-сессию', () => this.toggle(), 'button dark');
    const reset = this.button('↺', 'Сбросить таймер', () => this.reset());
    this.select = this.element('select', 'duration-select'); this.select.setAttribute('aria-label', 'Длительность фокус-сессии');
    for (const minutes of [15, 25, 45]) { const option = this.element('option', '', `${minutes} мин`); option.value = minutes; this.select.append(option); }
    this.select.value = this.duration; this.listen(this.select, 'change', () => { this.duration = Number(this.select.value); this.reset(); });
    this.categorySelect = this.element('select','focus-category'); this.categorySelect.setAttribute('aria-label','Категория фокус-сессии');
    for(const category of ['Творчество','Развитие','Личное']) { const option=this.element('option','',category); option.value=category; this.categorySelect.append(option); }
    this.categorySelect.value=this.category; this.listen(this.categorySelect,'change',()=>{this.category=this.categorySelect.value;this.changed();});
    const hint=this.element('p','focus-hint','Выбери одно дело. Подари ему всё внимание.');
    footer.append(this.start, reset, this.select); this.content.append(hint, this.categorySelect, inner, footer); this.update(); return root;
  }
  toggle() {
    if (this.running) this.pause();
    else {
      if (this.remaining <= 0) this.remaining = this.duration * 60;
      this.running = true; this.deadline = Date.now() + this.remaining * 1000;
      this.interval = setInterval(() => this.tick(), 250);
      this.update(); this.changed();
    }
  }
  tick() {
    this.remaining = Math.max(0, Math.ceil((this.deadline - Date.now()) / 1000));
    this.update();
    if (!this.remaining) { this.pause(); this.dashboard.recordSession(this.duration, this.category); this.caption.textContent = 'СЕССИЯ ЗАВЕРШЕНА. ВРЕМЯ ВЫДОХНУТЬ.'; this.dashboard.announce('Фокус-сессия завершена'); }
  }
  pause() { if (this.running) this.remaining = Math.max(0, Math.ceil((this.deadline - Date.now()) / 1000)); this.running = false; clearInterval(this.interval); this.update(); this.changed(); }
  reset() { this.running = false; clearInterval(this.interval); this.remaining = this.duration * 60; this.caption.textContent = 'ОДНА ЗАДАЧА. ПОЛНОЕ ВНИМАНИЕ.'; this.update(); this.changed(); }
  update() {
    if (!this.value) return;
    this.value.textContent = `${String(Math.floor(this.remaining / 60)).padStart(2, '0')}:${String(this.remaining % 60).padStart(2, '0')}`;
    this.start.textContent = this.running ? 'Пауза' : 'Начать'; this.start.setAttribute('aria-label', this.running ? 'Поставить таймер на паузу' : 'Начать фокус-сессию');
    this.select.disabled = this.running;
    if(this.categorySelect) this.categorySelect.disabled=this.running;
    this.root.classList.toggle('focus-running', this.running);
    this.ring.style.setProperty('--progress', `${(1 - this.remaining / (this.duration * 60)) * 100}%`);
  }
  serialize() { const remaining = this.running ? Math.max(0, Math.ceil((this.deadline - Date.now()) / 1000)) : this.remaining; return { ...super.serialize(), state: { duration: this.duration, remaining, category: this.category } }; }
  destroy() { clearInterval(this.interval); super.destroy(); }
}


// dist/js/charts.js

function makeElement(tag,className='',text){const node=document.createElement(tag);node.className=className;if(text!==undefined)node.textContent=text;return node;}
function svgElement(tag,attrs={}){const node=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[key,value]of Object.entries(attrs))node.setAttribute(key,String(value));return node;}
function barChart(days,{maxHeight=140,unit='мин'}={}){const chart=makeElement('div','activity-chart');const max=Math.max(60,...days.map(d=>d.value));chart.setAttribute('role','img');chart.setAttribute('aria-label',days.map(d=>`${d.label}: ${d.value} ${unit}`).join('; '));const axis=makeElement('div','chart-axis');[max,Math.round(max*.66),Math.round(max*.33),0].forEach(v=>axis.append(makeElement('span','',v)));const plot=makeElement('div','chart-columns');plot.style.height=`${maxHeight+34}px`;days.forEach((day,i)=>{const column=makeElement('div','activity-column');const bar=makeElement('div',`activity-bar${i===days.length-1?' highlighted':''}`);bar.style.height=`${Math.max(4,day.value/max*maxHeight)}px`;bar.title=`${day.value} ${unit}`;const value=makeElement('span','bar-tooltip',`${day.value} ${unit}`);bar.append(value);column.append(bar,makeElement('span','bar-label',day.label));plot.append(column);});chart.append(axis,plot);return chart;}
function lineChart(values,labels){const wrap=makeElement('div','line-chart');const svg=svgElement('svg',{viewBox:'0 0 620 180',role:'img','aria-label':values.map((v,i)=>`${labels[i]}: ${v} минут`).join('; '),preserveAspectRatio:'none'});const max=Math.max(60,...values);[25,65,105,145].forEach(y=>svg.append(svgElement('line',{x1:15,y1:y,x2:605,y2:y,stroke:'#eeeaf4','stroke-width':1})));const points=values.map((v,i)=>[15+i*(590/Math.max(1,values.length-1)),145-v/max*120]);const area=svgElement('polygon',{points:[[15,155],...points,[605,155]].map(p=>p.join(',')).join(' '),fill:'#ede5fa'});const line=svgElement('polyline',{points:points.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#a389c6','stroke-width':3,'stroke-linecap':'round','stroke-linejoin':'round'});svg.append(area,line);points.forEach(([cx,cy],i)=>{const dot=svgElement('circle',{cx,cy,r:4,fill:'#fff',stroke:'#a389c6','stroke-width':2});const title=svgElement('title');title.textContent=`${labels[i]}: ${values[i]} мин`;dot.append(title);svg.append(dot);});const ticks=makeElement('div','line-ticks');const step=Math.max(1,Math.ceil(labels.length/7));labels.forEach((label,i)=>{if(i%step===0||i===labels.length-1)ticks.append(makeElement('span','',label));});wrap.append(svg,ticks);return wrap;}


// dist/js/RhythmWidget.js




class RhythmWidget extends UIComponent {
  constructor(config,dashboard){super({...config,title:'Часы внимания'},dashboard);this.period=7;}
  render(){const root=super.render();this.listen(this.dashboard.events,'data',()=>this.update());this.listen(this.content,'change',event=>{if(event.target.name==='period'){this.period=Number(event.target.value);this.update();}});this.update();return root;}
  update(){const days=Array.from({length:this.period},(_,i)=>{const date=dateOffset(i-this.period+1);return {label:new Date(`${date}T12:00:00`).toLocaleDateString('ru-RU',{weekday:'short'}),value:this.dashboard.sessions.filter(s=>s.date===date).reduce((sum,s)=>sum+s.minutes,0)};});const total=days.reduce((sum,d)=>sum+d.value,0);const heading=this.element('div','widget-subheading');const totalText=this.element('span','subtle-text');totalText.append(this.element('strong','accent-text',`${Math.round(total/60*10)/10} ч`),document.createTextNode(' за последние дни'));const select=this.element('select','period-select');select.name='period';select.setAttribute('aria-label','Период активности');for(const[value,text]of[[7,'Неделя'],[14,'2 недели']]){const option=this.element('option','',text);option.value=value;select.append(option);}select.value=this.period;heading.append(totalText,select);this.content.replaceChildren(heading,barChart(days),this.element('p','chart-note','Твой ритм, без гонки за продуктивностью.'));}
}


// dist/js/APIWidget.js


const CITIES = { moscow: { name: 'Москва', lat: 55.75, lon: 37.62 }, petersburg: { name: 'Петербург', lat: 59.94, lon: 30.31 }, kazan: { name: 'Казань', lat: 55.79, lon: 49.12 }, sochi: { name: 'Сочи', lat: 43.6, lon: 39.73 }, kaliningrad: { name: 'Калининград', lat: 54.71, lon: 20.51 } };
class APIWidget extends UIComponent {
  constructor(config, dashboard) { super(config, dashboard); this.city = Object.hasOwn(CITIES, config.state?.city) ? config.state.city : 'moscow'; }
  render() {
    const root = super.render(); this.output = this.element('div'); this.output.setAttribute('aria-live', 'polite');
    const footer = this.element('div', 'api-source');
    this.citySelect = this.element('select', 'city-select'); this.citySelect.setAttribute('aria-label', `Город: ${this.title}`);
    for (const [key, city] of Object.entries(CITIES)) { const option = this.element('option', '', city.name); option.value = key; this.citySelect.append(option); }
    this.citySelect.value = this.city;
    this.listen(this.citySelect, 'change', () => { this.city = this.citySelect.value; this.changed(); void this.load(); });
    const refresh = this.button('↻', `Обновить: ${this.title}`, () => void this.load());
    footer.append(this.citySelect, this.element('span', '', 'Open-Meteo'), refresh);
    this.content.append(this.output, footer); void this.load(); return root;
  }
  showState(text, state) { this.output.dataset.state = state; this.output.replaceChildren(this.element('p', `api-state ${state}`, text)); }
  async load() {
    this.request?.abort(); clearTimeout(this.timeout);
    const request = new AbortController(); this.request = request;
    this.showState('Узнаём, что снаружи…', 'loading');
    this.output.setAttribute('aria-busy', 'true');
    this.timeout = setTimeout(() => request.abort('timeout'), 12000);
    try {
      const response = await fetch(this.url(CITIES[this.city]), { signal: request.signal });
      if (!response.ok) throw new Error('API unavailable');
      const data = await response.json();
      if (this.destroyed || this.request !== request) return;
      if (!this.hasData(data)) this.showState('Для этого города пока нет данных.', 'empty');
      else { this.output.dataset.state = 'success'; this.showData(data); }
    } catch (error) {
      if (this.destroyed || this.request !== request || (request.signal.aborted && request.signal.reason !== 'timeout')) return;
      this.showState('Не удалось получить данные. Попробуй обновить.', 'error');
    } finally {
      if (this.request === request) { clearTimeout(this.timeout); this.output.setAttribute('aria-busy', 'false'); }
    }
  }
  serialize() { return { ...super.serialize(), state: { city: this.city } }; }
  destroy() { this.request?.abort(); clearTimeout(this.timeout); super.destroy(); }
}


// dist/js/WeatherWidget.js


class WeatherWidget extends APIWidget {
  constructor(config, dashboard) { super({ ...config, title: 'За окном', symbol: '☼' }, dashboard); }
  url(city) { return `https://api.open-meteo.com/v1/forecast?latitude=${city.lat}&longitude=${city.lon}&current=temperature_2m,apparent_temperature,weather_code&timezone=auto`; }
  hasData(data) { return Number.isFinite(data?.current?.temperature_2m); }
  showData(data) {
    const current = data.current;
    const code = current.weather_code;
    const description = code === 0 ? 'Ясно' : code <= 3 ? 'Облачно' : code <= 48 ? 'Туман' : code <= 67 ? 'Дождь' : code <= 77 ? 'Снег' : code <= 86 ? 'Осадки' : 'Гроза';
    const main = this.element('div', 'weather-main');
    const icon = this.element('span', 'weather-icon', code === 0 ? '☼' : code <= 3 ? '☁' : '☂'); icon.setAttribute('aria-hidden', 'true');
    main.append(this.element('div', 'big-number', `${Math.round(current.temperature_2m)}°`), icon);
    const feels = Number.isFinite(current.apparent_temperature) ? ` · ощущается как ${Math.round(current.apparent_temperature)}°` : '';
    this.output.replaceChildren(main, this.element('p', 'api-details', `${description}${feels}`));
  }
}


// dist/js/AirWidget.js


class AirWidget extends APIWidget {
  constructor(config, dashboard) { super({ ...config, title: 'Воздух вокруг', symbol: '≈' }, dashboard); }
  url(city) { return `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${city.lat}&longitude=${city.lon}&current=european_aqi,pm2_5&timezone=auto`; }
  hasData(data) { return Number.isFinite(data?.current?.european_aqi); }
  showData(data) {
    const aqi = Math.max(0, Math.round(data.current.european_aqi));
    const category = aqi <= 20 ? 0 : aqi <= 40 ? 1 : aqi <= 60 ? 2 : aqi <= 80 ? 3 : aqi <= 100 ? 4 : 5;
    const labels = ['Хороший', 'Удовлетворительный', 'Умеренный', 'Плохой', 'Очень плохой', 'Крайне плохой'];
    const main = this.element('div', 'air-index'); main.append(this.element('div', 'big-number', aqi), this.element('span', 'pill', labels[category]));
    const meter = this.element('div', 'air-meter'); meter.setAttribute('aria-hidden', 'true'); for (let i = 0; i < 6; i++) meter.append(this.element('span', i === category ? 'active' : ''));
    this.output.replaceChildren(main, meter, this.element('p', 'api-details', 'Европейский индекс AQI · ниже — лучше'));
  }
}


