const QUOTES = ['Не обязательно успеть всё. Достаточно сделать место для важного.', 'Внимание — это то, из чего складывается твой день.', 'Маленький шаг тоже меняет расстояние.', 'Пауза — часть ритма, а не его отсутствие.', 'Одна законченная мысль ценнее десяти открытых вкладок.'];
class QuoteWidget extends UIComponent {
  constructor(config, dashboard) { super({ ...config, title: 'Мысль дня', symbol: '“' }, dashboard); this.index = Number.isInteger(config.state?.index) && config.state.index >= 0 && config.state.index < QUOTES.length ? config.state.index : 0; }
  render() { const root = super.render(); this.quote = this.element('p', 'quote-text', QUOTES[this.index]); const footer = this.element('div', 'quote-footer'); footer.append(this.element('span', '', 'Заметки DAYFORM'), this.button('Другая мысль', 'Показать другую мысль', () => { this.index = (this.index + 1 + Math.floor(Math.random() * (QUOTES.length - 1))) % QUOTES.length; this.quote.textContent = QUOTES[this.index]; this.changed(); }, '')); this.content.append(this.quote, footer); return root; }
  serialize() { return { ...super.serialize(), state: { index: this.index } }; }
}


// dist/js/DataWidget.js


class DataWidget extends UIComponent {
  render() { const root=super.render();this.store=this.dashboard.store;this.listen(this.store,'date',()=>this.update());this.listen(this.dashboard.events,'data',()=>this.refresh());this.listen(this.content,'click',event=>{const button=event.target.closest('[data-action]');if(button)this.action(button.dataset.action,button,event);});this.listen(this.content,'change',event=>this.change(event));this.listen(this.content,'submit',event=>{event.preventDefault();try{this.submit(event.target,new FormData(event.target));const input=this.content.querySelector('form input[name=text],form input[name=name]');if(input)input.value='';}catch(error){this.message(error.message);}});this.update();return root; }
  refresh() {
    // Updating a chart elsewhere must not erase an unfinished form here.
    const drafts = [...this.content.querySelectorAll('form')].map(form => Object.fromEntries(new FormData(form)));
    const focus = document.activeElement;
    const focusedName = this.content.contains(focus) && focus.closest('form') ? focus.name : null;
    this.update();
    [...this.content.querySelectorAll('form')].forEach((form, index) => {
      for (const field of form.elements) if (field.name && drafts[index]?.[field.name] !== undefined) field.value = drafts[index][field.name];
      if (focusedName) for (const field of form.elements) if (field.name === focusedName) field.focus();
    });
  }
  action(){} change(){} submit(){} update(){}
  actionButton(text,action,label=text){const button=this.element('button','small-button',text);button.type='button';button.dataset.action=action;button.setAttribute('aria-label',label);return button;}
  input(name,label,type='text',value=''){const input=this.element('input','field');input.name=name;input.type=type;input.setAttribute('aria-label',label);input.placeholder=label;input.value=value;return input;}
  select(name,label,options,value){const select=this.element('select','field');select.name=name;select.setAttribute('aria-label',label);for(const [id,text]of options){const option=this.element('option','',text);option.value=id;select.append(option);}if(value!==undefined)select.value=value;return select;}
  submitButton(text){const button=this.element('button','button dark',text);button.type='submit';return button;}
  message(text){this.dashboard.announce(text);let message=this.content.querySelector('.error-inline');if(!message){message=this.element('p','error-inline');message.setAttribute('role','alert');this.content.append(message);}message.textContent=text;}
  empty(text){return this.element('p','widget-empty',text);}
}


// dist/js/CalendarWidget.js



class CalendarWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'Календарь',symbol:'▦'},dashboard);this.month=new Date();this.month.setDate(1);}
  update(){const title=this.month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});const header=this.element('div','calendar-month');header.append(this.actionButton('‹','previous','Предыдущий месяц'),this.element('strong','',title),this.actionButton('›','next','Следующий месяц'));const weekdays=this.element('div','calendar-weekdays');['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].forEach(d=>weekdays.append(this.element('span','',d)));const grid=this.element('div','calendar-days');const offset=(this.month.getDay()+6)%7;const days=new Date(this.month.getFullYear(),this.month.getMonth()+1,0).getDate();for(let i=0;i<offset;i++)grid.append(this.element('span','blank-day'));for(let d=1;d<=days;d++){const date=dayKey(new Date(this.month.getFullYear(),this.month.getMonth(),d));const button=this.actionButton(String(d),'date',new Date(`${date}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}));button.dataset.date=date;button.className='calendar-day';button.classList.toggle('today',date===dayKey());button.classList.toggle('chosen',date===this.store.selectedDate);button.setAttribute('aria-pressed',String(date===this.store.selectedDate));if(this.store.data.schedule.some(s=>s.date===date))button.classList.add('has-event');grid.append(button);}const foot=this.element('div','calendar-foot');foot.append(this.element('span','','● Есть планы'),this.actionButton('Сегодня','today'));this.content.replaceChildren(header,weekdays,grid,foot);}
  action(action,button){if(action==='date'){this.store.selectDate(button.dataset.date);this.dashboard.navigate('plan');}if(action==='today'){this.month=new Date();this.month.setDate(1);this.store.selectDate(dayKey());this.update();}if(action==='previous'||action==='next'){this.month.setMonth(this.month.getMonth()+(action==='next'?1:-1));this.update();}}
}


// dist/js/ScheduleWidget.js



class ScheduleWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'Расписание дня'},dashboard);this.editing=false;}
  update(){const date=this.store.selectedDate;const events=this.store.data.schedule.filter(s=>s.date===date).sort((a,b)=>a.time.localeCompare(b.time));const dateRow=this.element('div','widget-subheading');const input=this.input('selected','День расписания','date',date);input.className='date-control';dateRow.append(input,this.actionButton(this.editing?'Скрыть':'＋ Событие','edit'));const list=this.element('div','schedule-list');events.forEach(item=>{const row=this.element('div',`schedule-row${item.done?' finished':''}`);const time=this.element('span','schedule-time',item.time);const badge=this.element('span',`schedule-icon category-${item.category==='Творчество'?0:item.category==='Развитие'?1:2}`);badge.append(icon(item.category==='Творчество'?'projects':item.category==='Развитие'?'note':'habits'));const text=this.element('div','schedule-text');text.append(this.element('strong','',item.text),this.element('small','',`${item.category} · ${item.duration} мин`));const check=this.actionButton(item.done?'✓':'○','toggle',`${item.done?'Отменить отметку':'Завершить'}: ${item.text}`);check.dataset.id=item.id;check.className='event-check';check.setAttribute('aria-pressed',String(item.done));row.append(time,badge,text,check);if(this.editing){const remove=this.actionButton('×','delete',`Удалить событие: ${item.text}`);remove.dataset.id=item.id;row.append(remove);}list.append(row);});if(!events.length)list.append(this.empty('Свободный день. Добавь что-нибудь важное.'));this.content.replaceChildren(dateRow,list);if(this.editing){const form=this.element('form','inline-form');const text=this.input('text','Название события');text.required=true;text.maxLength=160;const time=this.input('time','Время','time','10:00');time.required=true;const duration=this.input('duration','Минуты','number','30');duration.min=5;duration.max=240;form.append(text,time,duration,this.select('category','Категория',[['Творчество','Творчество'],['Развитие','Развитие'],['Личное','Личное']]),this.submitButton('Добавить'));this.content.append(form);} }
  action(action,button){if(action==='edit'){this.editing=!this.editing;this.update();if(this.editing)this.content.querySelector('[name=text]').focus();}if(action==='toggle')this.store.toggleEvent(button.dataset.id);if(action==='delete')this.store.deleteEvent(button.dataset.id);}
  change(event){if(event.target.name==='selected')this.store.selectDate(event.target.value);}
  submit(form,values){this.store.addEvent({text:values.get('text'),time:values.get('time'),duration:Number(values.get('duration')),category:values.get('category'),date:this.store.selectedDate});this.content.querySelector('[name=text]')?.focus();}
}


// dist/js/ProjectsWidget.js




class ProjectsWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'Проекты в движении'},dashboard);this.editing=false;}
  update(){const top=this.element('div','widget-subheading');top.append(this.element('span','subtle-text',`${this.store.data.projects.length} проектов · каждый шаг имеет значение`),this.actionButton(this.editing?'Скрыть':'＋ Проект','edit'));const list=this.element('div','project-list');for(const project of this.store.data.projects){const progress=this.store.progress(project.id);const row=this.element('div','project-row');const badge=this.element('span','project-icon');badge.style.background=`${COLORS[project.color]}55`;badge.append(icon('projects'));const details=this.element('div','project-details');details.append(this.element('strong','',project.name),this.element('small','',project.description||project.category));const track=this.element('div','project-progress');const bar=this.element('div','progress-track');const fill=this.element('i');fill.style.width=`${progress.percent}%`;fill.style.background=COLORS[project.color];bar.append(fill);track.append(this.element('small','',`${progress.done} / ${progress.total} задач`),bar);const percentage=this.element('div','progress-ring',`${progress.percent}%`);percentage.style.setProperty('--value',`${progress.percent}%`);percentage.style.setProperty('--color',COLORS[project.color]);row.append(badge,details,track,percentage);list.append(row);}if(!this.store.data.projects.length)list.append(this.empty('Собери большой замысел из маленьких шагов.'));this.content.replaceChildren(top,list);if(this.editing){const form=this.element('form','inline-form project-form');const name=this.input('name','Название проекта');name.maxLength=80;name.required=true;const description=this.input('description','Короткое описание');description.maxLength=240;const due=this.input('due','Дедлайн','date');due.required=true;form.append(name,description,due,this.select('category','Категория',[['Творчество','Творчество'],['Развитие','Развитие'],['Личное','Личное']]),this.submitButton('Создать проект'));this.content.append(form);}else{const link=this.element('a','text-link','Открыть доску проектов');link.href='#projects';this.content.append(link);} }
  action(action){if(action==='edit'){this.editing=!this.editing;this.update();if(this.editing)this.content.querySelector('[name=name]').focus();}}
  submit(form,values){this.store.addProject(Object.fromEntries(values));this.editing=false;this.update();this.dashboard.announce('Проект создан');}
}


// dist/js/BoardWidget.js



class BoardWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'От идеи к результату'},dashboard);this.filter='all';this.editing=false;}
  update(){if(this.filter!=='all'&&!this.store.data.projects.some(p=>p.id===this.filter))this.filter='all';const heading=this.element('div','widget-subheading');heading.append(this.select('filter','Фильтр проекта',[['all','Все проекты'],...this.store.data.projects.map(p=>[p.id,p.name])],this.filter),this.actionButton(this.editing?'Скрыть':'＋ Задача','edit'));const board=this.element('div','kanban');const statuses=[['todo','Запланировано'],['doing','В работе'],['done','Готово']];for(const[status,title]of statuses){const column=this.element('section',`kanban-column column-${status}`);const cards=this.store.data.cards.filter(c=>c.status===status&&(this.filter==='all'||c.project===this.filter));const name=this.element('div','kanban-heading');name.append(this.element('h3','',title),this.element('span','count',cards.length));column.append(name);for(const card of cards){const project=this.store.data.projects.find(p=>p.id===card.project);const item=this.element('article','kanban-card');const label=this.element('span','project-badge',project.name);label.style.background=`${COLORS[project.color]}35`;const remove=this.actionButton('×','delete',`Удалить карточку: ${card.text}`);remove.dataset.id=card.id;const upper=this.element('div','kanban-card-top');upper.append(label,remove);const select=this.select('status',`Статус: ${card.text}`,statuses,card.status);select.dataset.id=card.id;const bottom=this.element('div','kanban-card-bottom');bottom.append(this.element('span','',new Date(`${card.due}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})),select);item.append(upper,this.element('h4','',card.text),bottom);column.append(item);}if(!cards.length)column.append(this.empty('Пока пусто'));board.append(column);}this.content.replaceChildren(heading,board);if(this.editing){const form=this.element('form','inline-form');const text=this.input('text','Название задачи');text.required=true;text.maxLength=160;const due=this.input('due','Дата задачи','date',this.store.selectedDate);due.required=true;form.append(text,this.select('project','Проект',this.store.data.projects.map(p=>[p.id,p.name]),this.filter==='all'?undefined:this.filter),due,this.submitButton('Добавить задачу'));if(!this.store.data.projects.length)form.append(this.empty('Сначала создай проект в карточке ниже.'));this.content.append(form);} }
  action(action,button){if(action==='edit'){this.editing=!this.editing;this.update();if(this.editing)this.content.querySelector('[name=text]').focus();}if(action==='delete')this.store.deleteCard(button.dataset.id);}
  change(event){if(event.target.name==='filter'){this.filter=event.target.value;this.update();}if(event.target.name==='status'){const id=event.target.dataset.id;this.store.moveCard(id,event.target.value);for(const select of this.content.querySelectorAll('[name=status]'))if(select.dataset.id===id)select.focus();}}
  submit(form,values){this.store.addCard(Object.fromEntries(values));this.content.querySelector('[name=text]')?.focus();}
}


// dist/js/DeadlinesWidget.js




class DeadlinesWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'На горизонте'},dashboard);}
  update(){const list=this.element('div','deadline-list');const cards=this.store.data.cards.filter(c=>c.status!=='done').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);for(const card of cards){const project=this.store.data.projects.find(p=>p.id===card.project);const row=this.element('a','deadline-item');row.href='#projects';const mark=this.element('span','deadline-mark','✳');mark.style.background=`${COLORS[project.color]}44`;const text=this.element('div');text.append(this.element('strong','',card.text),this.element('small','',`${project.name} · ${new Date(`${card.due}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}`));const tag=this.element('span',`status-tag ${card.due<dayKey()?'overdue':card.status}`,card.due<dayKey()?'Просрочено':card.status==='doing'?'В работе':'В планах');row.append(mark,text,tag);list.append(row);}this.content.replaceChildren(cards.length?list:this.empty('Ближайших дедлайнов нет. Можно выдохнуть.'));}
}


// dist/js/HabitTrackerWidget.js





class HabitTrackerWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'Привычки, которые остаются'},dashboard);this.offset=0;this.editing=false;}
  update(){const heading=this.element('div','widget-subheading');const range=this.element('div','habit-range');range.append(this.actionButton('‹','previous','Предыдущая неделя'),this.element('span','',this.offset===0?'Последние 7 дней':`${Math.abs(this.offset)} дней назад`),this.actionButton('›','next','Следующая неделя'));heading.append(range,this.actionButton(this.editing?'Скрыть':'＋ Привычка','edit'));const days=Array.from({length:7},(_,i)=>dateOffset(this.offset-6+i));const table=this.element('div','habit-table');const names=this.element('div','habit-table-heading');names.append(this.element('span','','Ритуал'));for(const date of days){const cell=this.element('span',date===dayKey()?'today-label':'');const d=new Date(`${date}T12:00:00`);cell.append(this.element('small','',d.toLocaleDateString('ru-RU',{weekday:'short'})),this.element('strong','',d.getDate()));names.append(cell);}names.append(this.element('span','',''));table.append(names);for(const habit of this.store.data.habits){const row=this.element('div','habit-table-row');const name=this.element('span','habit-name');const symbol=this.element('i');symbol.append(icon(habit.icon));name.append(symbol,this.element('strong','',habit.name));row.append(name);for(const date of days){const done=habit.days.includes(date);const button=this.actionButton(done?'✓':'','toggle',`${habit.name}, ${date}`);button.dataset.id=habit.id;button.dataset.date=date;button.className=`habit-check${done?' checked':''}`;button.setAttribute('aria-pressed',String(done));row.append(button);}const remove=this.actionButton('×','delete',`Удалить привычку: ${habit.name}`);remove.dataset.id=habit.id;row.append(remove);table.append(row);}this.content.replaceChildren(heading,this.store.data.habits.length?table:this.empty('Добавь маленький ритуал и начни с сегодняшнего дня.'));if(this.editing){const form=this.element('form','inline-form');const input=this.input('name','Название привычки');input.required=true;input.maxLength=60;form.append(input,this.submitButton('Добавить привычку'));this.content.append(form);}this.content.append(this.element('p','chart-note','Каждая отметка — небольшой вклад в себя. Можно отмечать прошедшие дни.'));}
  action(action,button){if(action==='previous'){this.offset-=7;this.update();}if(action==='next'){this.offset=Math.min(0,this.offset+7);this.update();}if(action==='edit'){this.editing=!this.editing;this.update();if(this.editing)this.content.querySelector('[name=name]').focus();}if(action==='toggle'){const id=button.dataset.id,date=button.dataset.date;this.store.toggleHabit(id,date);for(const cell of this.content.querySelectorAll('[data-action=toggle]'))if(cell.dataset.id===id&&cell.dataset.date===date)cell.focus();}if(action==='delete')this.store.deleteHabit(button.dataset.id);}
  submit(form,values){this.store.addHabit(values.get('name'));this.content.querySelector('[name=name]')?.focus();}
}


// dist/js/AnalyticsWidget.js




const TITLES={trend:'Как меняется твой ритм',distribution:'Куда уходит внимание',heatmap:'Календарь постоянства',balance:'Баланс проектов'};
class AnalyticsWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:TITLES[config.type]||'Аналитика'},dashboard);this.period=14;}
  update(){const header=this.element('div','widget-subheading');header.append(this.element('span','subtle-text',this.type==='heatmap'?'Отметки привычек за 12 недель':this.type==='distribution'?'Фокус-сессии по категориям':this.type==='balance'?'Завершённые задачи по проектам':'Минуты сосредоточенной работы'));if(this.type==='trend')header.append(this.select('period','Период графика',[['7','7 дней'],['14','14 дней'],['30','30 дней']],String(this.period)));this.content.replaceChildren(header);if(this.type==='trend')this.renderTrend();if(this.type==='distribution')this.renderDistribution();if(this.type==='heatmap')this.renderHeatmap();if(this.type==='balance')this.renderBalance();}
  change(event){if(event.target.name==='period'){this.period=Number(event.target.value);this.update();}}
  renderTrend(){const days=Array.from({length:this.period},(_,i)=>dateOffset(i-this.period+1));const values=days.map(date=>this.dashboard.sessions.filter(s=>s.date===date).reduce((sum,s)=>sum+s.minutes,0));const total=values.reduce((a,b)=>a+b,0);const summary=this.element('div','chart-summary');const value=this.element('strong','',total);value.append(this.element('small','','мин за период'));summary.append(value,this.element('span','soft-badge',`${Math.round(total/this.period)} мин в среднем`));this.content.append(summary,lineChart(values,days.map(date=>new Date(`${date}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}))),this.element('p','chart-note','Завершённые сессии учитываются в день окончания.'));}
  renderDistribution(){const categories=['Творчество','Развитие','Личное'];const values=categories.map(category=>this.dashboard.sessions.filter(s=>(s.category||'Личное')===category).reduce((sum,s)=>sum+s.minutes,0));const total=values.reduce((a,b)=>a+b,0);const layout=this.element('div','donut-layout');const donut=this.element('div','donut');let start=0;const stops=values.map((value,i)=>{const end=start+(total?value/total*100:0);const segment=`${COLORS[i]} ${start}% ${end}%`;start=end;return segment;});donut.style.background=total?`conic-gradient(${stops.join(',')})`:'#eeeaf3';donut.setAttribute('role','img');donut.setAttribute('aria-label',categories.map((c,i)=>`${c}: ${values[i]} минут`).join('; '));const center=this.element('div','donut-center');center.append(this.element('strong','',Math.round(total/60*10)/10),this.element('small','','часов фокуса'));donut.append(center);const legend=this.element('div','donut-legend');categories.forEach((category,i)=>{const row=this.element('div');const color=this.element('i');color.style.background=COLORS[i];row.append(color,this.element('span','',category),this.element('strong','',`${total?Math.round(values[i]/total*100):0}%`));legend.append(row);});layout.append(donut,legend);this.content.append(layout,this.element('p','chart-note','Категория выбирается перед запуском таймера.'));}
  renderHeatmap(){const heatmap=this.element('div','heatmap');heatmap.setAttribute('role','img');const today=new Date();const monday=new Date(today);monday.setDate(monday.getDate()-((monday.getDay()+6)%7)-77);const weeks=[];for(let week=0;week<12;week++){const column=this.element('div','heatmap-column');for(let day=0;day<7;day++){const date=dateOffset(week*7+day,monday);const count=this.store.data.habits.filter(h=>h.days.includes(date)).length;const cell=this.element('span',`heatmap-cell level-${Math.min(4,count)}`);if(date>dateOffset(0))cell.classList.add('future');cell.title=`${date}: ${count} привычек`;column.append(cell);weeks.push(`${date}: ${count}`);}heatmap.append(column);}heatmap.setAttribute('aria-label',`Отметки привычек по дням. ${weeks.join('; ')}`);const legend=this.element('div','heatmap-legend');legend.append(this.element('span','','Меньше'));for(let i=0;i<=4;i++)legend.append(this.element('i',`heatmap-cell level-${i}`));legend.append(this.element('span','','Больше'));this.content.append(heatmap,legend,this.element('p','chart-note','Постоянство складывается из маленьких повторений.'));}
  renderBalance(){const list=this.element('div','balance-list');for(const project of this.store.data.projects){const progress=this.store.progress(project.id);const row=this.element('div','balance-row');const top=this.element('div');top.append(this.element('strong','',project.name),this.element('span','',`${progress.done} из ${progress.total} · ${progress.percent}%`));const bar=this.element('div','progress-track');const fill=this.element('i');fill.style.width=`${progress.percent}%`;fill.style.background=COLORS[project.color];bar.append(fill);row.append(top,bar);list.append(row);}this.content.append(this.store.data.projects.length?list:this.empty('Создай проект и добавь задачи — здесь появится его прогресс.'));}
}


// dist/main.js
const el = makeElement;




















const lifecycle=new AbortController();
document.querySelector('#server-hint').hidden=true;
const on=(target,event,handler)=>target.addEventListener(event,handler,{signal:lifecycle.signal});
const entries=[['todo',ToDoWidget,'Задачи','Приоритеты и дела на выбранный день'],['rhythm',RhythmWidget,'Часы внимания','Активность за одну или две недели'],['focus',FocusWidget,'Фокус','Таймер с категориями занятий'],['calendar',CalendarWidget,'Календарь','Выбор даты и отметки событий'],['schedule',ScheduleWidget,'Расписание','События с временем и длительностью'],['projects',ProjectsWidget,'Проекты','Прогресс, описание и дедлайны'],['board',BoardWidget,'Доска задач','От плана к готовому результату'],['deadlines',DeadlinesWidget,'На горизонте','Ближайшие задачи проектов'],['habits',HabitTrackerWidget,'Привычки','Отметки по дням и неделям'],['heatmap',AnalyticsWidget,'Постоянство','Тепловая карта привычек'],['trend',AnalyticsWidget,'Динамика фокуса','Линейный график за 7, 14 или 30 дней'],['distribution',AnalyticsWidget,'Внимание','Кольцевая диаграмма категорий'],['balance',AnalyticsWidget,'Баланс проектов','Завершённые задачи проектов'],['note',NoteWidget,'Заметка','Место для мыслей'],['quote',QuoteWidget,'Мысль дня','Небольшое напоминание'],['weather',WeatherWidget,'Погода','Настоящие данные за окном'],['air',AirWidget,'Качество воздуха','Настоящий европейский индекс AQI'],['habit',HabitWidget,'Ритуалы первой версии','Независимые ежедневные отметки']];
const pages={overview:['Обзор','Хороший день для важного','Собери свой день из того, что имеет значение.'],plan:['План дня','Всё начинается с одного шага','Задачи, встречи и мысли — в одном ритме.'],projects:['Проекты','Идеи становятся реальностью','Большие замыслы. Маленькие, понятные шаги.'],habits:['Привычки','Маленькие действия. Большие перемены.','Постоянство без перфекционизма.'],analytics:['Аналитика','Посмотри на свой ритм','Замечай закономерности и находи свой баланс.']};
let dashboard,mode='demo',page='overview';
try{mode=localStorage.getItem('dayform.mode')==='personal'?'personal':'demo';}catch{}
function navigate(route){if(!pages[route])route='overview';if(location.hash!==`#${route}`)location.hash=route;else showPage(route,true);}
function showPage(route,focus=false){page=pages[route]?route:'overview';document.querySelectorAll('.route-page').forEach(section=>section.hidden=section.id!==`page-${page}`);document.querySelectorAll('[data-page]').forEach(link=>{const active=link.dataset.page===page;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.querySelector('#breadcrumb-page').textContent=pages[page][0].toUpperCase();const title=document.querySelector('#page-title');title.replaceChildren(document.createTextNode(pages[page][1]),el('span','greeting-star','✳'));document.querySelector('#page-subtitle').textContent=pages[page][2];document.title=`${pages[page][0]} · DAYFORM`;dashboard?.showPage(page);if(focus){title.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function loadWorkspace(nextMode){if(dashboard)dashboard.destroy();document.querySelectorAll('.dashboard').forEach(container=>container.replaceChildren());mode=nextMode;try{localStorage.setItem('dayform.mode',mode);}catch{}dashboard=new Dashboard(document.querySelector('#overview-widgets'),{mode,navigate});entries.forEach(([type,Widget,title,description])=>dashboard.register(type,Widget,{title,description}));dashboard.restore();dashboard.currentPage=page;dashboard.events.addEventListener('data',renderMetrics,{signal:dashboard.lifecycle.signal});document.querySelectorAll('[data-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mode===mode)));document.querySelector('#demo-caption').textContent=mode==='demo'?'Пример заполненного пространства':'Твои данные, только в этом браузере';document.querySelector('#reset-workspace').textContent=mode==='demo'?'Сбросить демо':'Сбросить мои данные';document.querySelector('#arrange').setAttribute('aria-pressed','false');document.querySelectorAll('.dashboard').forEach(grid=>grid.classList.remove('arranging'));showPage(page);renderMetrics();}
function metric(title,value,unit,detail,tag,kind){const card=el('article','metric-card');const heading=el('div','metric-heading');const symbol=el('span','metric-icon');symbol.append(icon(kind));heading.append(symbol,el('span','',title));const number=el('div','metric-value',value);number.append(el('small','',unit));const foot=el('div','metric-foot');foot.append(el('span','',detail));if(tag)foot.append(el('span','metric-tag',tag));card.append(heading,number,foot);return card;}
function renderMetrics(){const tasks=dashboard.tasks;const today=dayKey();const todayTasks=tasks.filter(t=>t.date===today);const done=todayTasks.filter(t=>t.done).length;const minutes=dashboard.sessions.filter(s=>s.date===today).reduce((sum,s)=>sum+s.minutes,0);const habits=dashboard.store.data.habits;const habitDone=habits.filter(h=>h.days.includes(today)).length;const projects=dashboard.store.data.projects;const cards=dashboard.store.data.cards;const complete=cards.filter(c=>c.status==='done').length;const totalMinutes=dashboard.sessions.reduce((sum,s)=>sum+s.minutes,0);document.querySelector('#overview-metrics').replaceChildren(metric('Главное на сегодня',`${done}/${todayTasks.length}`,'задач','Маленькие шаги вперёд',todayTasks.length?`${Math.round(done/todayTasks.length*100)}% готово`:'Чистый лист','todo'),metric('Время для важного',minutes,'мин','Фокус сегодня',`${dashboard.sessions.filter(s=>s.date===today).length} сессии`,'focus'),metric('Твои ритуалы',`${habitDone}/${habits.length}`,'привычек','Забота о себе, каждый день',habitDone?'Хороший ритм':'Начни с малого','habits'));document.querySelector('#project-metrics').replaceChildren(metric('В движении',projects.length,'проектов','От идеи к результату','','projects'),metric('Завершено',complete,'задач','По всем проектам',cards.length?`${Math.round(complete/cards.length*100)}% готово`:'','todo'),metric('В работе',cards.filter(c=>c.status==='doing').length,'задач','То, что двигает тебя вперёд','','board'));const weekDays=Array.from({length:7},(_,i)=>dateOffset(-i));const weekCount=habits.reduce((sum,h)=>sum+h.days.filter(d=>weekDays.includes(d)).length,0);const streaks=habits.map(h=>{let streak=0;let offset=h.days.includes(today)?0:-1;while(streak<730&&h.days.includes(dateOffset(offset-streak)))streak++;return streak;});document.querySelector('#habit-metrics').replaceChildren(metric('Сегодня',habitDone,'отметки',`${habits.length} привычек в пространстве`,'','habits'),metric('За эту неделю',weekCount,'повторений','Последние семь дней',habits.length?`${Math.round(weekCount/(habits.length*7)*100)}%`:'','calendar'),metric('Лучшая текущая серия',Math.max(0,...streaks),'дней','Включая вчера, если день ещё идёт','','trend'));document.querySelector('#analytics-metrics').replaceChildren(metric('Всего внимания',Math.round(totalMinutes/60*10)/10,'часов',`${dashboard.sessions.length} завершённых сессий`,'','focus'),metric('Сделано',tasks.filter(t=>t.done).length+complete,'задач','Личные задачи и проекты','','todo'),metric('Привычки в действии',habits.reduce((sum,h)=>sum+h.days.length,0),'отметки','Каждое повторение считается','','habits'));}
document.querySelectorAll('[data-icon]').forEach(node=>node.append(icon(node.dataset.icon)));
document.querySelector('#date-label').textContent=new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
showPage(location.hash.slice(1));loadWorkspace(mode);
on(window,'hashchange',()=>showPage(location.hash.slice(1),true));
document.querySelectorAll('[data-mode]').forEach(button=>on(button,'click',()=>{if(button.dataset.mode!==mode){loadWorkspace(button.dataset.mode);dashboard.announce(mode==='demo'?'Открыт демопример':'Открыты личные данные');}}));
on(document.querySelector('#reset-workspace'),'click',()=>{const message=mode==='demo'?'Сбросить демопример? Все изменения в демо будут удалены, и пример вернётся к изначальному состоянию.':'Сбросить мои данные? Все добавленные задачи, проекты, привычки, события, статистика и изменения расположения будут удалены. Пространство вернётся к изначальному состоянию. Это действие нельзя отменить.';if(!confirm(message))return;const resetMode=mode;if(dashboard){dashboard.destroy({save:false});dashboard=null;}try{localStorage.removeItem(`dayform.v2.${resetMode}`);if(resetMode==='personal')localStorage.removeItem('dayform.v1');}catch{}loadWorkspace(resetMode);dashboard.announce(resetMode==='demo'?'Демопример восстановлен до изначального состояния':'Мои данные сброшены до изначального состояния');});
const dialog=document.querySelector('#widget-dialog');let opener;
on(document.querySelector('#add-widget'),'click',event=>{opener=event.currentTarget;document.querySelector('#catalog-error').textContent='';dialog.showModal();});
on(dialog,'close',()=>{if(document.activeElement===document.body||dialog.contains(document.activeElement))opener?.focus();});
const options=document.querySelector('#widget-options');for(const[type,,title,description]of entries.filter(item=>item[0]!=='habit')){const button=el('button','widget-option');button.type='button';const symbol=el('span','option-symbol');symbol.append(icon(type));button.append(symbol,el('strong','',title),el('span','',description));on(button,'click',()=>{try{const widget=dashboard.addWidget(type,{page});dialog.close();widget.root.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});widget.minimizeButton.focus();dashboard.announce(`Виджет «${widget.title}» добавлен`);}catch(error){document.querySelector('#catalog-error').textContent=error.message;}});options.append(button);}
on(document.querySelector('#arrange'),'click',event=>{dashboard.setArranging(!dashboard.arranging);event.currentTarget.setAttribute('aria-pressed',String(dashboard.arranging));});
on(document.querySelector('#quick-focus'),'click',()=>{let widget=dashboard.widgets.find(w=>w.type==='focus');if(!widget)widget=dashboard.addWidget('focus',{page:'overview',placement:'aside'});navigate(widget.page);if(widget.minimized)widget.minimize();requestAnimationFrame(()=>{widget.root.scrollIntoView({block:'center'});widget.start.focus();});});
on(document.querySelector('#help-button'),'click',()=>document.querySelector('#help-dialog').showModal());
on(document,'visibilitychange',()=>{if(document.hidden)dashboard.save();});
on(window,'pagehide',event=>{dashboard.save();if(!event.persisted){dashboard.destroy();lifecycle.abort();}});
if(document.modelContext?.registerTool){const tool={name:'dayform_add_task',title:'Добавить задачу в DAYFORM',description:'Добавляет задачу на выбранную дату в активное пространство DAYFORM (демопример или личные данные).',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:180}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.text!=='string'||!input.text.trim()||input.text.length>180||Object.keys(input).some(key=>key!=='text'))throw new Error('Ожидается текст задачи от 1 до 180 символов');const widget=dashboard.widgets.find(w=>w.type==='todo')??dashboard.addWidget('todo',{page:'plan'});return widget.addTask(input.text);}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(error=>console.warn('WebMCP unavailable',error));}catch(error){console.warn('WebMCP unavailable',error);}}
